/**
 Do not return anything, modify board in-place instead.
 */
function solve(board: string[][]): void {
  const m = board.length;
  const n = board[0].length;
  const dirs = [
    [1, 0],
    [-1, 0],
    [0, 1],
    [0, -1],
  ];

  // Помечаем '#' все 'O', достижимые из клетки (r, c) на краю доски
  const markSafe = (r: number, c: number): void => {
    if (board[r][c] !== 'O') return;
    board[r][c] = '#';
    const stack: number[][] = [[r, c]];
    while (stack.length) {
      const [cr, cc] = stack.pop()!;
      for (const [dr, dc] of dirs) {
        const nr = cr + dr;
        const nc = cc + dc;
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && board[nr][nc] === 'O') {
          board[nr][nc] = '#';
          stack.push([nr, nc]);
        }
      }
    }
  };

  // 1. Обходим только граничные клетки: левый и правый столбцы, верхнюю и нижнюю строки
  for (let i = 0; i < m; i++) {
    markSafe(i, 0);
    markSafe(i, n - 1);
  }
  for (let j = 0; j < n; j++) {
    markSafe(0, j);
    markSafe(m - 1, j);
  }

  // 2. Оставшиеся 'O' не связаны с краем — захватываем их,
  //    а помеченные '#' возвращаем обратно в 'O'
  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (board[i][j] === 'O') board[i][j] = 'X';
      else if (board[i][j] === '#') board[i][j] = 'O';
    }
  }
}

// Время: O(m · n) — каждая клетка помечается и перекрашивается не более одного раза
// Память: O(m · n) — стек обхода в худшем случае
